// Quiz game · script.js

// Step 6: the questions, as an array of objects
const questions = [
  {
    text: "Which keyword declares a constant?",
    options: ["var", "let", "const", "static"],
    answer: 2
  },
  {
    text: "What does typeof 42 return?",
    options: ["number", "string", "integer", "decimal"],
    answer: 0
  },
  {
    text: "Which method adds an item to the end of an array?",
    options: ["pop()", "push()", "shift()", "join()"],
    answer: 1
  },
  {
    text: "What is 3 + '3' in JavaScript?",
    options: ["6", "NaN", "undefined", "'33'"],
    answer: 3
  },
  {
    text: "Which operator checks the value and the type?",
    options: ["==", "===", "=", "=>"],
    answer: 1
  }
];

console.log(questions.length);
console.log(questions[0].text);

// Step 7: the Quiz class keeps the questions, the position and the score
class Quiz {
  constructor(questions) {
    this.questions = questions;
    this.index = 0;
    this.score = 0;
  }

  currentQuestion() {
    return this.questions[this.index];
  }

  checkAnswer(choice) {
    const isRight = choice === this.currentQuestion().answer;
    if (isRight) {
      this.score++;
    }
    return isRight;
  }

  nextQuestion() {
    this.index++;
  }

  isFinished() {
    return this.index >= this.questions.length;
  }

  // Step 12: the score as a percentage
  percentage() {
    return Math.round((this.score / this.questions.length) * 100);
  }
}

// Step 7: try the class with a quiz just for testing
const test = new Quiz(questions);
console.log(test.checkAnswer(2), test.score);
test.nextQuestion();
console.log(test.index, test.isFinished());

// Step 8: the elements of the page
const startScreen = document.querySelector("#start-screen");
const quizScreen = document.querySelector("#quiz-screen");
const endScreen = document.querySelector("#end-screen");
const secondsInput = document.querySelector("#seconds");
const startBtn = document.querySelector("#start-btn");
const progressText = document.querySelector("#progress");
const timerText = document.querySelector("#timer");
const scoreText = document.querySelector("#score");
const questionText = document.querySelector("#question");
const answerButtons = document.querySelectorAll(".answer");
const feedback = document.querySelector("#feedback");
const nextBtn = document.querySelector("#next-btn");
const finalScore = document.querySelector("#final-score");
const finalMessage = document.querySelector("#final-message");
const restartBtn = document.querySelector("#restart-btn");

let quiz;

// Show one screen and hide the other two
function showScreen(screen) {
  startScreen.hidden = screen !== startScreen;
  quizScreen.hidden = screen !== quizScreen;
  endScreen.hidden = screen !== endScreen;
}

function showQuestion() {
  const question = quiz.currentQuestion();
  progressText.textContent = `Question ${quiz.index + 1} of ${quiz.questions.length}`;
  questionText.textContent = question.text;
  answerButtons.forEach((button, i) => {
    button.textContent = question.options[i];
    button.disabled = false;
    button.classList.remove("correct", "wrong");
  });
  feedback.textContent = "";
  nextBtn.hidden = true;
  startTimer();
}

function startQuiz() {
  quiz = new Quiz(questions);
  seconds = parseInt(secondsInput.value);
  if (isNaN(seconds) || seconds < 1) {
    seconds = 15;
  }
  scoreText.textContent = "Score: 0";
  showScreen(quizScreen);
  showQuestion();
}

startBtn.addEventListener("click", startQuiz);
showScreen(startScreen);

// Step 9: right or wrong?
function showRightAnswer() {
  const question = quiz.currentQuestion();
  answerButtons.forEach((button) => {
    button.disabled = true;
  });
  answerButtons[question.answer].classList.add("correct");
  nextBtn.hidden = false;
}

function answer(choice) {
  clearInterval(timerId);
  const question = quiz.currentQuestion();
  const isRight = quiz.checkAnswer(choice);
  showRightAnswer();
  if (isRight) {
    feedback.textContent = "Correct! Well done.";
  } else {
    answerButtons[choice].classList.add("wrong");
    feedback.textContent = `Not quite! The right answer is ${question.options[question.answer]}.`;
  }
  scoreText.textContent = `Score: ${quiz.score}`;
}

answerButtons.forEach((button, i) => {
  button.addEventListener("click", () => answer(i));
});

// Step 10: the next question, or the end of the quiz
function showResults() {
  const percent = quiz.percentage();
  finalScore.textContent = `You got ${quiz.score} of ${quiz.questions.length} right (${percent}%)`;
  finalMessage.textContent = getMessage(percent);
  showScreen(endScreen);
}

nextBtn.addEventListener("click", () => {
  quiz.nextQuestion();
  if (quiz.isFinished()) {
    showResults();
  } else {
    showQuestion();
  }
});

// Step 11: the countdown
let seconds = 15;
let timeLeft = 0;
let timerId = null;

function startTimer() {
  clearInterval(timerId);
  timeLeft = seconds;
  timerText.textContent = timeLeft;
  timerId = setInterval(() => {
    timeLeft--;
    timerText.textContent = timeLeft;
    if (timeLeft <= 0) {
      clearInterval(timerId);
      timeUp();
    }
  }, 1000);
}

function timeUp() {
  const question = quiz.currentQuestion();
  showRightAnswer();
  feedback.textContent = `Time's up! The right answer is ${question.options[question.answer]}.`;
}

// Step 12: an encouraging message and «Play again»
function getMessage(percent) {
  if (percent >= 80) {
    return "Excellent! You really know your JavaScript.";
  }
  if (percent >= 50) {
    return "Good job! A bit more practice and you'll ace it.";
  }
  return "Nice try! Play again and beat your score.";
}

restartBtn.addEventListener("click", startQuiz);
